from typing import List, Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class ReactionsMethods(BaseClient):
    """
    Методы группы 'Реакции' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("reactions.rapi_reaction_add")
    def rapi_reaction_add(self, msgId: int, chatId: str, reactions: List[str], reaction: str) -> dict:
        """
        Добавление реакции к сообщению

        Этот метод сперва пробует найти существующие реакции
        для заданной пары сообщение/чат.
        Если они есть и reaction существует в списке,
        к ним применится добавление реакции пользователя.
        Если их нет, они будут созданы с присланным список reactions
        и к ним применится добавление реакции пользователя.
        Список reactions в параметрах на данный момент является обязательным.

        :param msgId: ID сообщения
        :param chatId: ID чата
        :param reactions: список доступных реакций
        :param reaction: добавляемая реакция
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/reaction/add",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "msgId": msgId,
                    "chatId": chatId,
                    "reactions": reactions,
                    "reaction": reaction,
                },
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("reactions.rapi_reaction_remove")
    def rapi_reaction_remove(self, msgId: int, chatId: str) -> dict:
        """
        Удаление реакции на сообщение

        :param msgId: ID сообщения
        :param chatId: ID чата
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/reaction/remove",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"msgId": msgId, "chatId": chatId},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("reactions.rapi_reaction_get")
    def rapi_reaction_get(self, chatId: str, msgIds: List[int]) -> dict:
        """
        Получение счетчиков реакций и подписка на них
        :param msgIds: ID сообщений
        :param chatId: ID чата
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/reaction/get",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"msgIds": msgIds, "chatId": chatId},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("reactions.rapi_reaction_list")
    def rapi_reaction_list(
        self,
        msgId: int,
        chatId: str,
        reaction: str,
        olderThan: Optional[str] = None,
        limit: int = 20,
    ) -> dict:
        """
        Получение списка поставивших реакции
        :param msgId: ID сообщения
        :param chatId: ID чата
        :param reaction:
        :param newerThan:
        :param olderThan:
        :param limit:
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/reaction/list",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "msgId": msgId,
                    "chatId": chatId,
                    "reaction": reaction,
                    "olderThan": olderThan,
                    "limit": limit,
                },
            },
        )
